mapper.select:
SELECT * FROM skill_repository WHERE name = #{name} AND active = 1

    AND tenant_id = #{tenantId}

LIMIT 1

mapper.insert:
INSERT INTO skill_repository (
tenant_id, name, url, branch, source_type, source_config, version, description, status, is_public, creator, active, create_time, update_time
) VALUES (
#{tenantId}, #{name}, #{url}, #{branch}, #{sourceType}, #{sourceConfig}, #{version}, #{description}, #{status}, #{isPublic}, #{creator}, #{active}, #{createTime}, #{updateTime}
)

mapper.select:
SELECT * FROM skill_repository
WHERE active = 1
AND (is_public = 1 OR creator = #{currentUsername})


    AND (tenant_id = #{tenantId}

        OR name = #{builtinName}

    )


    AND name LIKE CONCAT('%', #{name}, '%')


    AND source_type = #{sourceType}


    AND status = #{status}

ORDER BY status DESC, update_time DESC
